def eval_postfix(tokens):
    stack = []
    for token in tokens:
        if token in ('+', '-', '*', '/'):
            if len(stack) < 2:
                raise ValueError('操作数不足：%r' % (tokens,))
            right = stack.pop()
            left = stack.pop()
            if token == '+':
                stack.append(left + right)
            elif token == '-':
                stack.append(left - right)
            elif token == '*':
                stack.append(left * right)
            else:
                stack.append(int(left / right))
        else:
            try:
                stack.append(int(token))
            except ValueError:
                raise ValueError('非法 token：%r' % (token,))
    if len(stack) != 1:
        raise ValueError('表达式非法：%r' % (tokens,))
    return stack[0]

print(eval_postfix(['3', '4', '+']))
print(eval_postfix(['3', '4', '+', '5', '*']))
print(eval_postfix(['5', '1', '2', '+', '4', '*', '+', '3', '-']))
print(eval_postfix(['-7', '2', '/']))

checks:
_bad = False
try:
    eval_postfix(['+'])
except ValueError:
    _bad = True
assert _bad, '操作数不足的表达式（只有一个加号）应抛出 ValueError'

_bad = False
try:
    eval_postfix(['1', '2'])
except ValueError:
    _bad = True
assert _bad, '扫完后剩两个操作数（1 和 2）不合法，应抛出 ValueError'

_bad = False
try:
    eval_postfix(['1', '+', '2'])
except ValueError:
    _bad = True
assert _bad, '后缀表达式里运算符位置不对应抛出 ValueError'

_bad = False
try:
    eval_postfix([])
except ValueError:
    _bad = True
assert _bad, '空表达式应抛出 ValueError'

_bad = False
try:
    eval_postfix(['1', '2', '+', '+'])
except ValueError:
    _bad = True
assert _bad, '多出一个运算符导致操作数不足，应抛出 ValueError'
